// ArchMap homepage — renders the recorded demo in site/demo-data.js.
//
// The data is generated by `node scripts/flagship-demo.mjs --write-site` from a real CLI run on
// the synthetic examples/lending-desk sample. Nothing here scans, fetches, or computes graph
// results; it only presents the recorded output. The DOM is built with createElement and
// textContent, never innerHTML.

/* global document, window */

(function () {
  'use strict';

  const data = window.ARCHMAP_DEMO;

  function el(tag, props, children) {
    const node = document.createElement(tag);
    if (props) {
      for (const [key, value] of Object.entries(props)) {
        if (value === undefined || value === null || value === false) continue;
        if (key === 'className') node.className = value;
        else if (key === 'text') node.textContent = value;
        else node.setAttribute(key, value === true ? '' : String(value));
      }
    }
    for (const child of children || []) {
      if (child === null || child === undefined || child === false) continue;
      node.append(typeof child === 'string' ? document.createTextNode(child) : child);
    }
    return node;
  }

  const short = (sha) => (typeof sha === 'string' && /^[0-9a-f]{40}$/.test(sha) ? sha.slice(0, 7) : String(sha));
  const shortHash = (h) => (typeof h === 'string' ? h.replace(/^sha256:/, '').slice(0, 12) : '');

  function mountCtaFocus() {
    for (const link of document.querySelectorAll('[data-focus-target]')) {
      link.addEventListener('click', () => {
        const target = document.getElementById(link.getAttribute('data-focus-target'));
        if (target) window.setTimeout(() => target.focus({ preventScroll: true }), 0);
      });
    }
  }

  if (!data || !Array.isArray(data.steps)) {
    const panel = document.getElementById('step-panel');
    if (panel) panel.append(el('p', { text: 'The recorded example data (demo-data.js) could not be loaded.' }));
    mountCtaFocus();
    return;
  }

  const stepById = new Map(data.steps.map((s) => [s.id, s]));
  const graphs = { before: data.graph.before, after: data.graph.after };
  const titleOf = new Map();
  for (const node of [...graphs.before, ...graphs.after]) titleOf.set(node.id, node.title);
  const nodeTitle = (id) => titleOf.get(id) || id;

  document.getElementById('record-label').textContent =
    `Recorded run · synthetic sample · ArchMap ${data.archmap_version}`;

  // ---------------------------------------------------------------- shared pieces

  function commandLine(step) {
    return el('div', { className: 'term' }, [
      el('p', null, [el('span', { className: 'prompt', text: '$ ' }), step.command]),
      step.id === 'edit' || step.id === 'commit'
        ? null
        : el('p', { className: 'dim', text: `exit ${step.exit_code}` }),
    ]);
  }

  function kv(pairs) {
    const dl = el('dl', { className: 'kv' });
    for (const [k, v] of pairs) dl.append(el('dt', { text: k }), el('dd', { text: String(v) }));
    return dl;
  }

  function chip(text, kind) {
    return el('span', { className: `chip${kind ? ` ${kind}` : ''}`, text });
  }

  function rawJson(step) {
    return el('details', { className: 'raw' }, [
      el('summary', { text: 'Raw JSON output' }),
      el('pre', { className: 'json', tabindex: '0' }, [el('code', { text: JSON.stringify(step.output, null, 2) })]),
    ]);
  }

  function evidenceItem(e) {
    const where = `${e.path}${e.symbol ? `#${e.symbol}` : ''}`;
    return el('li', {
      text: [where, `blob ${shortHash(e.blob_hash)}`, e.commit ? `commit ${short(e.commit)}` : null, `${e.analyzer}@${e.analyzer_version}`]
        .filter(Boolean)
        .join(' · '),
    });
  }

  // ---------------------------------------------------------------- step renderers

  const renderers = {
    init(o) {
      return [kv([['project', o.project.name], ['project id', o.project.id], ['root', o.root]])];
    },
    scan(o) {
      return [kv([['files', o.files], ['nodes', o.nodes], ['base commit', short(o.base_commit)], ['dirty tree', o.dirty]])];
    },
    status(o) {
      const out = [
        el('p', null, [
          o.clean ? chip('clean', 'fresh') : chip('stale', 'stale'),
          ` snapshot at ${short(o.base_commit)} · ${o.file_count} files · ${o.node_count} nodes`,
        ]),
      ];
      if (o.diff && o.diff.modified.length > 0) {
        out.push(el('h5', { text: 'Modified since the snapshot' }));
        out.push(el('ul', { className: 'plain-list' }, o.diff.modified.map((p) => el('li', null, [el('span', { className: 'path', text: p })]))));
      }
      if (o.stale_nodes.length > 0) {
        out.push(el('h5', { text: 'Stale nodes' }));
        out.push(el('ul', { className: 'plain-list' }, o.stale_nodes.map((id) =>
          el('li', null, [el('span', { className: 'path', text: nodeTitle(id) }), el('span', { className: 'why', text: id })]))));
      }
      if (o.drift.length > 0) out.push(kv([['model drift', o.drift.join(', ')]]));
      return out;
    },
    context(o) {
      return [
        el('p', {
          text: `${o.included.length} nodes included, ${o.omitted.length} omitted · ~${o.used_tokens} of ${o.budget} estimated tokens (about four characters per token, not a tokenizer count)`,
        }),
        el('ul', { className: 'plain-list' }, o.included.map((s) =>
          el('li', null, [
            el('span', { className: 'path', text: s.node.title }),
            el('span', { className: 'why', text: `${s.reason} · ~${s.tokens} est. tokens` }),
          ]))),
      ];
    },
    impact(o) {
      return [
        el('p', { text: `Changed: ${o.requested_paths.join(', ')} · ${o.impacted.length} nodes affected` }),
        el('ul', { className: 'plain-list' }, o.impacted.map((e) =>
          el('li', null, [
            el('span', { className: 'path', text: e.title }),
            chip(e.kind),
            el('span', { className: 'why', text: e.reason }),
          ]))),
      ];
    },
    evidence(o) {
      const node = graphs.before.find((n) => n.id === o.target);
      const out = [el('p', { text: `${o.evidence.length} evidence pointers for ${node ? node.title : o.target}` })];
      if (node) {
        out.push(el('ul', { className: 'plain-list' }, node.relations.map((r) =>
          el('li', null, [
            el('span', { text: r.type }),
            el('span', { className: 'path', text: nodeTitle(r.target) }),
            chip(r.certainty, r.certainty),
          ]))));
      }
      out.push(el('ul', { className: 'evidence' }, o.evidence.map(evidenceItem)));
      return out;
    },
    edit(o) {
      return [
        kv([['file', o.path]]),
        el('code', { className: 'diff' }, [
          el('span', { className: 'del', text: `- ${o.before}` }),
          el('span', { className: 'add', text: `+ ${o.after}` }),
        ]),
      ];
    },
    commit(o) {
      return [kv([['new HEAD', short(o.commit)]])];
    },
  };
  const rendererFor = (id) =>
    renderers[id.replace(/-(clean|stale|fresh|partial|base)$/, '').replace(/^rescan$/, 'scan')];

  // ---------------------------------------------------------------- walkthrough

  const stepList = document.getElementById('steps');
  const panel = document.getElementById('step-panel');
  const stepButtons = [];

  function selectStep(index, focus) {
    const step = data.steps[index];
    stepButtons.forEach((b, i) => {
      if (i === index) b.setAttribute('aria-current', 'step');
      else b.removeAttribute('aria-current');
      b.tabIndex = i === index ? 0 : -1;
    });
    if (focus) stepButtons[index].focus();
    const body = rendererFor(step.id)(step.output);
    panel.replaceChildren(
      el('h4', { text: `${index + 1}. ${step.title}` }),
      el('p', { className: 'note', text: step.note }),
      commandLine(step),
      ...body,
      ...(step.id === 'edit' ? [] : [rawJson(step)]),
    );
  }

  data.steps.forEach((step, i) => {
    const button = el('button', { type: 'button', className: 'step-button' }, [
      el('span', { className: 'step-num', text: String(i + 1).padStart(2, '0') }),
      el('span', { text: step.title }),
      step.id === 'edit' || step.id === 'commit' ? el('span') : el('span', { className: 'exit', text: `exit ${step.exit_code}` }),
    ]);
    button.addEventListener('click', () => selectStep(i, false));
    button.addEventListener('keydown', (ev) => {
      const next = { ArrowDown: 1, ArrowRight: 1, ArrowUp: -1, ArrowLeft: -1 }[ev.key];
      if (ev.key === 'Home' || ev.key === 'End') {
        ev.preventDefault();
        selectStep(ev.key === 'Home' ? 0 : data.steps.length - 1, true);
      } else if (next) {
        ev.preventDefault();
        selectStep((i + next + data.steps.length) % data.steps.length, true);
      }
    });
    stepButtons.push(button);
    stepList.append(el('li', null, [button]));
  });
  selectStep(0, false);

  // ---------------------------------------------------------------- hero excerpt

  const impact = stepById.get('impact');
  const heroTerm = document.getElementById('hero-term');
  if (impact && heroTerm) {
    heroTerm.replaceChildren(
      el('p', null, [el('span', { className: 'prompt', text: '$ ' }), impact.command.replace(/ --json$/, '')]),
      el('p', { className: 'dim', text: `impact of ${impact.output.requested_paths.join(', ')}: ${impact.output.impacted.length} nodes affected` }),
      ...impact.output.impacted.map((e) =>
        el('p', { className: 'row' }, [el('span', { text: `  [${e.kind}] ${e.title}` }), el('span', { className: 'dim', text: e.reason })])),
    );
  }

  // ---------------------------------------------------------------- freshness timeline

  const timeline = document.getElementById('timeline');
  const scan = stepById.get('scan');
  const edit = stepById.get('edit');
  const stale = stepById.get('status-stale');
  const rescan = stepById.get('rescan');
  const fresh = stepById.get('status-fresh');
  if (timeline && scan && edit && stale && rescan && fresh) {
    timeline.append(
      el('li', null, [
        el('span', { className: 'when', text: `commit ${short(scan.output.base_commit)}` }),
        el('span', { className: 'what', text: 'First scan' }),
        chip('clean', 'fresh'),
        el('p', { text: `${scan.output.files} files mapped into ${scan.output.nodes} nodes.` }),
      ]),
      el('li', null, [
        el('span', { className: 'when', text: 'working tree' }),
        el('span', { className: 'what', text: `Edit ${edit.output.path}` }),
        el('code', { className: 'diff' }, [
          el('span', { className: 'del', text: `- ${edit.output.before}` }),
          el('span', { className: 'add', text: `+ ${edit.output.after}` }),
        ]),
      ]),
      el('li', null, [
        el('span', { className: 'when', text: `archmap status · exit ${stale.exit_code}` }),
        el('span', { className: 'what', text: 'Map is stale' }),
        chip('stale', 'stale'),
        el('p', { text: `Stale: ${stale.output.stale_nodes.map(nodeTitle).join(', ')}.` }),
      ]),
      el('li', null, [
        el('span', { className: 'when', text: `commit ${short(rescan.output.base_commit)}` }),
        el('span', { className: 'what', text: 'Rescan' }),
        chip(fresh.output.clean ? 'clean' : 'stale', fresh.output.clean ? 'fresh' : 'stale'),
        el('p', { text: `archmap status exits ${fresh.exit_code}; evidence now points at the new commit.` }),
      ]),
    );
  }

  // ---------------------------------------------------------------- sample browser

  const fileList = document.getElementById('file-list');
  const source = document.getElementById('source');
  const nodeInfo = document.getElementById('node-info');
  const mapButtons = { before: document.getElementById('map-before'), after: document.getElementById('map-after') };
  const fileButtons = [];
  let version = 'before';
  let currentPath = edit ? edit.output.path : data.files[0].path;

  function fileText(path) {
    const file = data.files.find((f) => f.path === path);
    if (!file) return '';
    if (version === 'after' && edit && path === edit.output.path) return file.text.replace(edit.output.before, edit.output.after);
    return file.text;
  }

  function renderSource(path) {
    const text = fileText(path).replace(/\n$/, '');
    const changed = version === 'after' && edit && path === edit.output.path ? edit.output.after : null;
    const lines = text.split('\n').map((line) => el('li', { className: line === changed ? 'changed' : null, text: line || ' ' }));
    source.replaceChildren(el('ol', null, lines));
    source.setAttribute('aria-label', `Source of ${path}${version === 'after' ? ' after the edit' : ''}`);
  }

  function relationBlock(r) {
    return el('div', { className: 'rel' }, [
      el('div', { className: 'rel-line' }, [
        el('span', { text: r.type }),
        el('span', { className: 'rel-target', text: nodeTitle(r.target) }),
        chip(r.certainty, r.certainty),
      ]),
      el('ul', { className: 'evidence', 'aria-label': 'Evidence' }, (r.evidence || []).map(evidenceItem)),
    ]);
  }

  function renderNodes(path) {
    const graph = graphs[version];
    // Most specific first: the file's own module before the directory and repository nodes.
    const scoped = graph
      .filter((n) => n.scope && Array.isArray(n.scope.files) && n.scope.files.includes(path))
      .sort((a, b) => a.scope.files.length - b.scope.files.length);
    const scopedIds = new Set(scoped.map((n) => n.id));
    const incoming = [];
    for (const n of graph) {
      for (const r of n.relations) if (scopedIds.has(r.target) && !scopedIds.has(n.id)) incoming.push({ from: n, rel: r });
    }

    const cards = scoped.map((n) =>
      el('article', { className: 'node-card' }, [
        el('header', null, [el('span', { className: 'title', text: n.title }), chip(n.kind)]),
        n.scope.symbols && n.scope.symbols.length > 0
          ? el('p', { className: 'muted', text: `Symbols: ${n.scope.symbols.join(', ')}` })
          : null,
        ...n.claims.map((c) => el('p', { className: 'muted', text: `Claim: ${c.text}` })),
        n.relations.length === 0
          ? el('p', { className: 'muted', text: 'No outgoing relations recorded.' })
          : null,
        ...n.relations.map(relationBlock),
      ]),
    );

    const referencedBy = incoming.length === 0 ? [] : [
      el('h4', { text: 'Referenced by' }),
      el('ul', { className: 'plain-list' }, incoming.map(({ from, rel }) =>
        el('li', null, [
          el('span', { className: 'path', text: from.title }),
          el('span', { className: 'why', text: `${rel.type} ${nodeTitle(rel.target)}` }),
          chip(rel.certainty, rel.certainty),
        ]))),
    ];
    nodeInfo.replaceChildren(
      el('h4', { text: `Nodes scoping ${path}` }),
      ...(cards.length > 0 ? cards : [el('p', { className: 'muted', text: 'No node scopes this file.' })]),
      ...referencedBy,
    );
  }

  function selectFile(path, focus) {
    currentPath = path;
    for (const b of fileButtons) {
      if (b.dataset.path === path) {
        b.setAttribute('aria-current', 'true');
        if (focus) b.focus();
      } else b.removeAttribute('aria-current');
    }
    renderSource(path);
    renderNodes(path);
  }

  for (const file of data.files) {
    const b = el('button', { type: 'button', className: 'file-button', text: file.path });
    b.dataset.path = file.path;
    b.addEventListener('click', () => selectFile(file.path, false));
    fileButtons.push(b);
    fileList.append(el('li', null, [b]));
  }

  function setVersion(next) {
    version = next;
    for (const [key, b] of Object.entries(mapButtons)) b.setAttribute('aria-pressed', String(key === next));
    selectFile(currentPath, false);
  }
  mapButtons.before.textContent = `First scan · ${short(data.commits.sample)}`;
  mapButtons.after.textContent = `After rescan · ${short(data.commits.edit)}`;
  mapButtons.before.addEventListener('click', () => setVersion('before'));
  mapButtons.after.addEventListener('click', () => setVersion('after'));

  selectFile(currentPath, false);
  mountCtaFocus();
})();
